const msgs = ($input.first().json.messages) || [];

// Recipient-side outcomes we do NOT count against our health (not our fault / not a filter)
const RECIPIENT = new Set([30003, 30004, 30005, 30006, 21610]); // unreachable, blocked-by-user, unknown, landline, opted-out
// Codes that mean the CARRIER filtered us or the number isn't accepted — the real canaries
const FILTERED = { 30032: 'Toll-free not verified / blocked', 30007: 'Carrier filtered (spam flag)', 30008: 'Unknown carrier error' };

const tally = {};
const filteredHits = [];
let terminal = 0, delivered = 0, recipientIssues = 0;

for (const m of msgs) {
  const s = m.status || 'unknown';
  tally[s] = (tally[s] || 0) + 1;
  const ec = m.error_code ? Number(m.error_code) : null;

  if (['delivered', 'undelivered', 'failed'].includes(s)) terminal++;
  if (s === 'delivered') delivered++;
  if (ec && RECIPIENT.has(ec)) recipientIssues++;
  if (ec && FILTERED[ec]) filteredHits.push({ to: m.to, code: ec, meaning: FILTERED[ec] });
}

// Delivery rate excluding recipient-side issues (we can't fix a landline)
const denom = terminal - recipientIssues;
const rate = denom > 0 ? Math.round((delivered / denom) * 100) : null;

// Decide severity
let level = 'ok';
const reasons = [];
if (filteredHits.some(h => h.code === 30032)) { level = 'critical'; reasons.push('Number rejected as unverified (30032) — the registration-mismatch canary'); }
if (filteredHits.some(h => h.code === 30007)) { level = level === 'critical' ? 'critical' : 'warning'; reasons.push('Carrier filtered messages as spam (30007)'); }
if (filteredHits.some(h => h.code === 30008)) { if (level === 'ok') level = 'warning'; reasons.push('Unknown carrier errors (30008)'); }
if (rate !== null && rate < 90 && denom >= 3) { if (level === 'ok') level = 'warning'; reasons.push(`Delivery rate ${rate}% is below 90%`); }

const alert = level !== 'ok';

const summary =
  `Twilio weekly health — ${'+18557748160'}\n` +
  `Texts sent (7d): ${msgs.length}\n` +
  `Delivered: ${delivered}${rate !== null ? `  (${rate}% of deliverable)` : ''}\n` +
  `By status: ${Object.entries(tally).map(([k,v]) => `${k}=${v}`).join(', ') || 'none'}\n` +
  `Recipient-side (landline/opted-out/unreachable, not our fault): ${recipientIssues}\n` +
  (filteredHits.length ? `\nCARRIER FLAGS:\n${filteredHits.map(h => `  ${h.to}  ${h.code} — ${h.meaning}`).join('\n')}\n` : '') +
  (reasons.length ? `\nWhy flagged:\n${reasons.map(r => '  - ' + r).join('\n')}\n` : '\nAll clear — nothing to act on.\n');

return [{ json: { alert, level, count: msgs.length, delivered, rate, summary } }];

